import{d as t,S as o,i as d,l as c}from"./chunks/framework.CY2TYXqZ.js";const m=JSON.parse('{"title":"Attack log export format, version 2","description":"","frontmatter":{},"headers":[],"relativePath":"reference/attack-log-export-format.md","filePath":"reference/attack-log-export-format.md"}'),a={name:"reference/attack-log-export-format.md"};function r(n,e,i,s,l,h){return o(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="attack-log-export-format-version-2" tabindex="-1">Attack log export format, version 2 <a class="header-anchor" href="#attack-log-export-format-version-2" aria-label="Permalink to “Attack log export format, version 2”">​</a></h1><p>An export contains <code>schemaVersion</code>, <code>policy</code>, <code>meta</code>, <code>challenge</code>, <code>session</code>, <code>traces</code>, and <code>integrity</code>. JSON is UTF-8. Markdown contains the identical logical package as a fenced JSON block, with an escaped title and a brief summary. A JSON export can be imported back from the page of the challenge it belongs to; Markdown cannot.</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>schemaVersion</code></td><td>Integer <code>1</code> or <code>2</code>; reject other versions. Version 1 has no <code>traces</code> field, which is not the same as an empty one: it can say nothing about activity rather than reporting none</td></tr><tr><td><code>policy.mode</code></td><td><code>full</code> or <code>thinned</code></td></tr><tr><td><code>policy.omittedResponseBodies</code>, <code>policy.omittedPanelViews</code></td><td>Nonnegative integer counts of omissions; both zero for full</td></tr><tr><td><code>meta.timezone</code>, <code>meta.exportedAt</code></td><td>IANA timezone and export date with UTC offset</td></tr><tr><td><code>meta.systemPrompt</code></td><td>Present only for solved sessions, including a solved timestamp of zero</td></tr><tr><td><code>meta.identity</code></td><td>Optional <code>name</code> and <code>className</code>; no authentication meaning</td></tr><tr><td><code>challenge</code></td><td>Slug, title and available challenge description/difficulty/category/backend</td></tr><tr><td><code>session</code></td><td><code>sessionId</code>, <code>startedAt</code>, nullable <code>solvedAt</code>, ordered <code>events</code>, nullable <code>draft</code></td></tr><tr><td><code>session.draft</code></td><td>Unexecuted stored code with <code>code</code> and <code>updatedAt</code>, or null if absent/unreadable</td></tr><tr><td><code>traces</code></td><td>Version 2 only. Activity recorded for this challenge <strong>before</strong> this export, each entry carrying <code>id</code>, <code>challengeSlug</code>, <code>at</code> and a <code>kind</code> of <code>exported</code>, <code>imported</code> or <code>removed</code> with that kind&#39;s own fields. Never the content of what was exported, imported or removed</td></tr><tr><td><code>integrity.algorithm</code></td><td><code>SHA-256</code></td></tr><tr><td><code>integrity.eventHashes</code></td><td>One lowercase hex digest per exported event, in order</td></tr><tr><td><code>integrity.checksum</code></td><td>Lowercase hex digest covering the entire package except this field</td></tr></tbody></table><h2 id="content-policy" tabindex="-1">Content policy <a class="header-anchor" href="#content-policy" aria-label="Permalink to “Content policy”">​</a></h2><p>Full preserves every event. Thinned removes <code>responseBody</code> from recognizable HTTP events and removes recognizable panel-view events. Requests, headers, code, notes, flag attempts and drafts remain. Unknown or malformed carried events remain unchanged, including a response body when the HTTP shape is unrecognized. Counts describe actual omissions, not the number of all HTTP or panel events. The database is not changed.</p><p>A recognizable <code>http_request</code> has numeric <code>timestamp</code>, <code>id</code>, <code>status</code>, <code>duration</code>; <code>source</code> is <code>browser</code>, <code>repeater</code> or <code>code</code>; <code>method</code>, <code>url</code>, <code>responseBody</code> are strings; <code>requestBody</code> is string or null; <code>requestHeaders</code> and <code>responseHeaders</code> are arrays of two-string pairs. Additional fields are preserved. A recognizable <code>panel_view</code> has numeric <code>timestamp</code> and string <code>panel</code>. This export policy does not introduce panel-view recording.</p><p>Identity removes C0/C1 controls and Unicode directional controls U+202A–U+202E and U+2066–U+2069, trims whitespace, and takes the first forty Unicode code points. Empty fields are omitted. Identity is transient: it is not written to the database. Filename components replace path separators, platform-reserved characters and controls; identity is optional. The filename ends in the export time, mode, and <code>.json</code> or <code>.md</code>.</p><h2 id="integrity-algorithm" tabindex="-1">Integrity algorithm <a class="header-anchor" href="#integrity-algorithm" aria-label="Permalink to “Integrity algorithm”">​</a></h2><ol><li>Snapshot the source before asynchronous hashing and apply the selected content policy.</li><li>Canonicalize JSON recursively: object keys sort lexicographically by UTF-16 code units; arrays keep their order; strings, booleans, null and finite numbers use JavaScript <code>JSON.stringify</code> encoding. There is no whitespace between tokens. Undefined and non-JSON values are invalid.</li><li>Let <code>H(value)</code> be SHA-256 of the UTF-8 bytes of that canonical JSON, encoded as lowercase hexadecimal. Start <code>previousHash</code> at sixty-four ASCII <code>0</code> characters.</li><li>For each exported event at zero-based <code>index</code>, calculate <code>H({index, previousHash, event})</code>, append it to <code>eventHashes</code>, and use it as the next <code>previousHash</code>. An empty timeline has an empty hash array.</li><li>Set <code>integrity.algorithm</code> and <code>integrity.eventHashes</code>. Compute the checksum over the complete package without <code>integrity.checksum</code>. Every other field, including identity and omission counts, is covered.</li></ol><p>The canonical form of <code>{&quot;z&quot;:[2,1],&quot;a&quot;:&quot;台灣&quot;}</code> is <code>{&quot;a&quot;:&quot;台灣&quot;,&quot;z&quot;:[2,1]}</code>. Implementations must use the specified JSON number and string encoding; arbitrary language-specific JSON serializers may differ. The repository&#39;s <code>attackLogExport.test.ts</code> compares Web Crypto hashes with Node&#39;s independent SHA-256 implementation.</p><p>Verification first validates the version, required shape and policy, recomputes the event chain, and then recomputes the checksum. A failed check rejects the package. A successful check means internal consistency only: anyone who edits the file can recompute all hashes. These hashes cannot prove authorship, uninterrupted recording, or the authenticity of an imported record. <code>traces</code> is covered by the checksum but not by the event chain, which describes events.</p><p>A package never contains the trace describing the export that produced it: that trace is written after the package is built, because a package cannot contain a record of itself and still match its own checksum. An empty or absent <code>traces</code> list is therefore not evidence that nothing happened — clearing all stored work on a device removes its traces, and version 1 packages have no such field. For Markdown, extract the fenced JSON and verify that logical package; changing the surrounding Markdown is outside checksum coverage.</p>',12)])])}const u=t(a,[["render",r]]);export{m as __pageData,u as default};
